/**
 * Test flow for createOrUpdateRecord action
 * Demonstrates creating or updating a record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testCreateOrUpdateRecord = Flow(
    {
        $id: Now.ID['test_create_or_update_record_flow'],
        name: 'Test Create Or Update Record',
        description: 'Tests the createOrUpdateRecord core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_create_or_update_record_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=received',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.createOrUpdateRecord,
            { $id: Now.ID['test_create_or_update_record_action'] },
            {
                table_name: 'incident',
                fields: TemplateValue({ number: 'INC0010001', short_description: 'Test Incident', priority: '3' }),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_create_or_update_record_log'] },
            {
                log_level: 'info',
                log_message: `createOrUpdateRecord outputs: record=${wfa.dataPill(result.record, 'string')}, table_name=${wfa.dataPill(result.table_name, 'string')}, status=${wfa.dataPill(result.status, 'string')}, error_message=${wfa.dataPill(result.error_message, 'string')}`,
            }
        )
    }
)
